def make_demo(h,w,bg,rects):
    g=[[bg]*w for _ in range(h)]
    expected=[[bg]*w for _ in range(h)]
    for r0,c0,r1,c1,col in rects:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    g[r][c]=expected[r][c]=col
                else:
                    expected[r][c]=7 if (r1-r0+1)%2 else 2
    return g,expected
